# %% ../nbs/src/00_trigonometry.ipynb #safe-code
def safe_divide(numerator: jax.Array, denominator: jax.Array, fill: float = 0.0) -> jax.Array:
    """Divide, returning ``fill`` where the denominator is exactly zero.

    Both the value and its gradient stay finite at ``denominator == 0``: the division
    uses a denominator of 1 wherever the true denominator vanishes, so reverse-mode never
    differentiates ``x / 0`` (a bare ``jnp.where(d != 0, x / d, fill)`` would still produce
    a NaN gradient from the untaken branch).

    This is scale independent: a small-but-valid denominator is divided by faithfully rather than
    being treated as zero, and a genuine zero yields ``fill`` instead of a huge finite
    number. `numerator` broadcasts against `denominator` as usual.
    """
    nonzero = denominator != 0
    safe_denominator = jnp.where(nonzero, denominator, 1.0)
    return jnp.where(nonzero, numerator / safe_denominator, fill)


def safe_norm(x: Float[jax.Array, "... dim"], axis: int = -1) -> Float[jax.Array, "..."]:
    """Return ``|x|``, with a finite (zero) gradient where ``|x| == 0``.

    `jnp.linalg.norm` has a NaN gradient at the origin, which propagates into every
    quantity computed from edge lengths as soon as a single edge collapses - a routine
    event in a vertex model. The sum of squares is guarded before the square root instead.
    """
    sq = jnp.sum(x**2, axis=axis)
    nonzero = sq > 0
    return jnp.where(nonzero, jnp.sqrt(jnp.where(nonzero, sq, 1.0)), 0.0)


def safe_normalize(x: Float[jax.Array, "... dim"], axis: int = -1) -> Float[jax.Array, "... dim"]:
    """Return ``x / |x|``, or the zero vector where ``|x| == 0``.

    NaN-gradient-safe and scale independent (see `safe_divide`). The sum of squares is
    guarded directly rather than going through `jnp.linalg.norm`, whose gradient is itself
    NaN at the origin.
    """
    sq = jnp.sum(x**2, axis=axis, keepdims=True)
    nonzero = sq > 0
    return jnp.where(nonzero, x / jnp.sqrt(jnp.where(nonzero, sq, 1.0)), 0.0)

# %% ../nbs/src/00_trigonometry.ipynb #7f22d2ad-1ddb-4cf3-b782-ef29639cb724
def get_circumcenter(a: Float[jax.Array, " dim"],
                     b: Float[jax.Array, " dim"],
                     c: Float[jax.Array, " dim"]) -> Float[jax.Array, " dim"]:
    """Circumcenter of triangle with vertices a, b, c via barycentric coordinates.

    Parameters
    ----------
    a, b, c : Float[Array, "dim"]
        Triangle vertex positions.

    Returns
    -------
    Float[Array, "dim"]
        Circumcenter coordinates.
    """
    la, lb, lc = jnp.linalg.norm(b - c), jnp.linalg.norm(c - a), jnp.linalg.norm(a - b)
    ba = la**2 * (lb**2 + lc**2 - la**2)
    bb = lb**2 * (lc**2 + la**2 - lb**2)
    bc = lc**2 * (la**2 + lb**2 - lc**2)
    return safe_divide(ba * a + bb * b + bc * c, ba + bb + bc)


def get_oriented_triangle_area(a: Float[jax.Array, " dim"],
                               b: Float[jax.Array, " dim"],
                               c: Float[jax.Array, " dim"]) -> Float[jax.Array, "*"]:
    """Signed area of triangle with vertices a, b, c.

    Parameters
    ----------
    a, b, c : Float[Array, "dim"]
        Triangle vertex positions (dim = 2 or 3).

    Returns
    -------
    Float[Array, "*"]
        Scalar (dim=2) or area-weighted normal vector (dim=3).
        In 2d, positive for counter-clockwise (a, b, c).
    """
    return 0.5 * jnp.cross(b - a, c - a)

def get_triangle_area_from_sides(u: Float[jax.Array, " dim"],
                                 v: Float[jax.Array, " dim"],
                                 ) -> Float[jax.Array, ""]:
    """Unsigned area of triangle edge vectors u, v

    Parameters
    ----------
    u, v : Float[Array, "dim"]
        Triangle edge vectors (any dimension)

    Returns
    -------
    Float[Array, ""]
        Triangle area.
    """
    x = (u**2).sum()*(v**2).sum() - ((u*v).sum())**2
    safe_x = jnp.where(x > 0.0, x, 1.0)
    return jnp.where(x > 0.0, jnp.sqrt(safe_x)/2, 0.0)

def get_triangle_area(a: Float[jax.Array, " dim"],
                      b: Float[jax.Array, " dim"],
                      c: Float[jax.Array, " dim"]) -> Float[jax.Array, ""]:
    """Unsigned area of triangle with vertices a, b, c.

    Parameters
    ----------
    a, b, c : Float[Array, "dim"]
        Triangle vertex positions (any dimension)

    Returns
    -------
    Float[Array, ""]
        Triangle area.
    """
    u, v = b - a, c - a
    return get_triangle_area_from_sides(u, v)


def get_polygon_area(pts: Float[jax.Array, "n_vertices 2"]) -> Float[jax.Array, ""]:
    """Signed area of a 2D simple polygon (shoelace formula).

    Positive for counter-clockwise vertex ordering. This matches the sign
    convention of `get_oriented_triangle_area`.

    Parameters
    ----------
    pts : Float[Array, "n_vertices 2"]
        Ordered polygon vertices.

    Returns
    -------
    Float[Array, ""]
        Signed area.
    """
    return jnp.sum(pts[:, 0] * jnp.roll(pts[:, 1], -1)
                   - jnp.roll(pts[:, 0], -1) * pts[:, 1]) / 2

